467	/// What the structural answer says of a component that decides which of the checker's props a collapsed layer takes
468	/// (the merge's `layer_checker_props`): the props it lists, the source each names (`parent`), and its inheritance layers, their
469	/// sources and members. A [`SemanticTarget`] carries it in a [`Layering`], so the checker can leave unconverted what the
470	/// merge leaves to a layer.
471	#[derive(Debug, Clone, Default, PartialEq, Eq, Hash)]
472	pub struct LayerFacts {
473	    /// The names of the props the structural answer lists.
474	    listed: std::collections::BTreeSet<String>,
475	    /// The `parent` of each prop it lists, each once.
476	    parents: Vec<PropParent>,
477	    /// Each inheritance layer's source, by type name and file.
478	    sources: Vec<(String, String)>,
479	    /// The members of every inheritance layer.
480	    members: std::collections::BTreeSet<String>,
481	    /// The notable members of its collapsed layers it does not list, with their source ([`layer_notable`]).
482	    notable: Vec<(String, PropParent)>,
483	}
484	
485	/// The notable members (`className`, `style`, …) of `entry`'s collapsed layers that it does not list itself, each with
486	/// its layer's source: the merge merges the checker's answer for each and moves it back to `notableInherited`.
487	fn layer_notable(entry: &ComponentEntry) -> Vec<(String, PropParent)> {
488	    let notable_names = crate::react_types::notable_html_attrs("");
489	    entry
490	        .inheritance
491	        .iter()
492	        .filter(|layer| layer.html_element.is_none())
493	        .flat_map(|layer| {
494	            layer
495	                .members
496	                .iter()
497	                .filter(|name| notable_names.contains(&name.as_str()) && !entry.props.contains_key(*name))
498	                .map(|name| {
499	                    (name.clone(), PropParent { name: layer.type_name.clone(), file_name: layer.file_name.clone() })
500	                })
501	        })
502	        .collect()
503	}
504	
505	impl LayerFacts {
506	    /// What `entry`, a structural answer, says.
507	    pub fn of(entry: &ComponentEntry) -> Self {
508	        let mut parents: Vec<PropParent> = Vec::new();
509	        for parent in entry.props.values().filter_map(|prop| prop.parent.as_ref()) {
510	            if !parents.contains(parent) {
511	                parents.push(parent.clone());
512	            }
513	        }
514	        Self {
515	            listed: entry.props.keys().cloned().collect(),
516	            parents,
517	            sources: entry.inheritance.iter().map(|layer| (layer.type_name.clone(), layer.file_name.clone())).collect(),
518	            members: entry.inheritance.iter().flat_map(|layer| layer.members.iter().cloned()).collect(),
519	            notable: layer_notable(entry),
520	        }
521	    }
522	}
