524	/// What the merge of the checker's answer into a component's structural answer is decided from besides the answer:
525	/// that structural answer's [`LayerFacts`] and the run's [`CollapseContext`]. A checker given it converts only the props
526	/// the merge keeps ([`Layering::kept`]), so the merge must be asked with the same structural answer and the same context:
527	/// otherwise it may keep a prop the checker did not convert ([`unconverted_type`]).
528	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
529	pub struct Layering {
530	    /// The structural answer's facts.
531	    pub facts: LayerFacts,
532	    /// The run's collapse choices.
533	    pub cx: CollapseContext,
534	}
535	
536	impl Layering {
537	    /// The layering of `entry`, a structural answer, under `cx`.
538	    pub fn of(entry: &ComponentEntry, cx: CollapseContext) -> Self {
539	        Self { facts: LayerFacts::of(entry), cx }
540	    }
541	
542	    /// Whether the merge can leave any prop to a layer: the structural answer has a layer, or the run collapses.
543	    pub fn may_layer(&self) -> bool {
544	        !self.facts.members.is_empty() || self.cx.mode != crate::types::options::CollapseInheritedProps::None
545	    }
546	
547	    /// Whether the structural answer lists a prop named `name`: the merge keeps such a prop whatever its source
548	    /// ([`Layering::kept`]), so only a prop it does not list can be left to a layer.
549	    pub fn lists(&self, name: &str) -> bool {
550	        self.facts.listed.contains(name)
551	    }
552	
553	    /// For each prop of a checker's answer, by name, `parent` and whether `@types/react` declares it, in the answer's
554	    /// order: whether the merge (`layer_checker_props`) keeps it. The same decision from the same inputs, read from the
555	    /// [`LayerFacts`] instead of the entry. An `@types/react` prop is always reported kept: whether the merge sees it at
556	    /// all is decided by its own filter first. `picked` is the answer's `SemanticComponent::picked`: those props reach
557	    /// by name and are kept, as the merge keeps them.
558	    pub fn kept(&self, props: &[(&str, Option<&PropParent>, bool)], picked: &[String]) -> Vec<bool> {
559	        let (layers, made) = checker_sources(&self.facts, props.iter().copied(), picked, self.cx);
560	        let layered: rustc_hash::FxHashSet<&str> = self
561	            .facts
562	            .members
563	            .iter()
564	            .map(String::as_str)
565	            .chain(layers.iter().flat_map(|layer| layer.members.iter().map(String::as_str)))
566	            .collect();
567	        props
568	            .iter()
569	            .map(|(name, parent, react_declared)| {
570	                *react_declared
571	                    || keeps(name, *parent, (&self.facts.notable, &made), self.facts.listed.contains(*name), &layered)
572	            })
573	            .collect()
574	    }
575	}
576	
577	/// The type a checker's prop has when the checker did not convert it, because the merge leaves it to a collapsed layer
578	/// ([`Layering::kept`]): its name and `parent` are all a layer reads. It is never merged as a prop's type.
579	pub fn unconverted_type() -> PropType {
580	    degraded_type("unconverted: left to a collapsed layer", OpaqueReason::UnsupportedExpression)
581	}
